381	     *  the sheet has a pool of the name already. */
382	    @Transactional
383	    public Pool add(String sheetId, String user, String name) {
384	        sheets.load(sheetId, user);
385	        sheets.lock(sheetId);
386	        if (pools.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
