396	    @Transactional
397	    public PoolMember addMember(String sheetId, String user, String poolName, long personId, BigDecimal share,
398	            LocalDate from, LocalDate to) {
399	        sheets.lock(sheetId);
400	        Pool pool = pools.findBySheetIdAndNameIgnoreCase(sheetId, poolName)
401	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
402	        Person person = people.findByIdAndSheetId(personId, sheetId)
