423	    /** Add another pool of the sheet to a pool with a share; refused (404) for a pool not on the
424	     *  sheet, (409) when the member pool is a member of a pool already, (422) when the pool would
425	     *  contain itself through any chain or the chain of pools would be more than three deep. */
426	    @Transactional
427	    public PoolMember addPoolMember(String sheetId, String user, String poolName, String memberName, BigDecimal share,
428	            LocalDate from, LocalDate to) {
429	        sheets.lock(sheetId);
430	        Pool pool = pools.findBySheetIdAndNameIgnoreCase(sheetId, poolName)
431	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
432	        Pool memberPool = pools.findBySheetIdAndNameIgnoreCase(sheetId, memberName)
433	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool"));
434	        if (members.findByMemberPoolId(memberPool.getId()).isPresent()) {
435	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The pool is a member of a pool already");
436	        }
437	        // the pool and the pools above it
438	        List<Long> above = new ArrayList<>();
439	        for (Long id = pool.getId(); id != null;
440	                id = members.findByMemberPoolId(id).map(PoolMember::getPoolId).orElse(null)) {
441	            above.add(id);
442	        }
443	        if (above.contains(memberPool.getId())) {
444	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A pool cannot contain itself");
445	        }
446	        if (above.size() + height(memberPool.getId()) > MAX_DEPTH) {
447	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
448	                    "A chain of pools is at most " + MAX_DEPTH + " deep");
449	        }
450	        PoolMember member = PoolMember.ofPool(pool.getId(), memberPool.getId(), share);
451	        member.setDates(from, to);
452	        member = members.saveAndFlush(member);
453	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
