458	    /** How deep the chain of pools from this one down is, counting this one. */
459	    private int height(Long poolId) {
460	        int below = 0;
461	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(List.of(poolId))) {
462	            if (m.getMemberPoolId() != null) {
463	                below = Math.max(below, height(m.getMemberPoolId()));
464	            }
465	        }
466	        return 1 + below;
467	    }
