682	package net.officefloor.hq.app.crew;
683	
684	import java.util.List;
685	import java.util.Map;
686	import java.util.stream.Collectors;
687	import net.officefloor.hq.app.Audit;
688	import net.officefloor.hq.app.person.Person;
689	import net.officefloor.hq.app.person.PersonRepository;
690	import net.officefloor.hq.app.sheet.SheetService;
691	import org.springframework.http.HttpStatus;
692	import org.springframework.stereotype.Service;
693	import org.springframework.transaction.annotation.Transactional;
694	import org.springframework.web.server.ResponseStatusException;
695	
696	@Service
697	public class CrewService {
698	
699	    /** A crew with its members, in the order they were added. */
700	    public record CrewWithMembers(Crew crew, List<CrewMember> members) {
701	    }
702	
703	    private final CrewRepository crews;
704	    private final CrewMemberRepository members;
705	    private final PersonRepository people;
706	    private final SheetService sheets;
707	    private final Audit audit;
708	
709	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
710	            SheetService sheets, Audit audit) {
711	        this.crews = crews;
712	        this.members = members;
713	        this.people = people;
714	        this.sheets = sheets;
715	        this.audit = audit;
716	    }
717	
718	    /** The sheet's crews in the order they were added, each with its members. */
719	    @Transactional(readOnly = true)
720	    public List<CrewWithMembers> list(String sheetId) {
721	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
722	        Map<Long, List<CrewMember>> byCrew = members.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList())
723	                .stream().collect(Collectors.groupingBy(CrewMember::getCrewId));
724	        return all.stream().map(c -> new CrewWithMembers(c, byCrew.getOrDefault(c.getId(), List.of()))).toList();
725	    }
726	
727	    /** Add a crew led by a person of the sheet; refused (404) for a person not on the sheet, (409)
728	     *  when the sheet has a crew of the name already. */
729	    @Transactional
730	    public Crew add(String sheetId, String user, String name, long leadId) {
731	        sheets.load(sheetId, user);
732	        sheets.lock(sheetId);
733	        Person lead = people.findByIdAndSheetId(leadId, sheetId)
734	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
735	        if (crews.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
736	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a crew of that name");
737	        }
738	        Crew crew = crews.saveAndFlush(new Crew(sheetId, name, lead.getId()));
739	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + name
740	                + " lead=" + lead.getName());
741	        return crew;
742	    }
743	
744	    /** Add a person of the sheet to a crew; refused (404) for a crew or person not on the sheet,
745	     *  (409) when the person is the crew's lead or in the crew already. */
746	    @Transactional
747	    public CrewMember addMember(String sheetId, String user, String crewName, long personId) {
748	        sheets.lock(sheetId);
749	        Crew crew = crews.findBySheetIdAndNameIgnoreCase(sheetId, crewName)
750	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew"));
751	        Person person = people.findByIdAndSheetId(personId, sheetId)
752	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
753	        if (crew.getLeadId().equals(person.getId())) {
754	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person leads the crew");
755	        }
756	        if (members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
757	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person is in the crew already");
758	        }
759	        CrewMember member = members.saveAndFlush(new CrewMember(crew.getId(), person.getId()));
760	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
761	                + " name=" + person.getName());
762	        return member;
763	    }
764	
765	    /** Carry a merged person's crews to the person they are merged into: the crews they lead are
766	     *  led by the other (who leaves the crew's members if among them), and their memberships move to
767	     *  the other unless the other leads the crew or is in it already. */
768	    @Transactional
769	    public void merge(Long fromId, Long intoId) {
770	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(fromId)) {
771	            crew.setLeadId(intoId);
772	            members.findByCrewIdInOrderByIdAsc(List.of(crew.getId())).stream()
773	                    .filter(m -> m.getPersonId().equals(intoId)).forEach(members::delete);
774	        }
775	        crews.flush();
776	        for (CrewMember member : members.findByPersonIdOrderByIdAsc(fromId)) {
777	            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
778	            if (crew.getLeadId().equals(intoId) || members.existsByCrewIdAndPersonId(crew.getId(), intoId)) {
779	                members.delete(member);
780	            } else {
781	                member.setPersonId(intoId);
782	            }
783	        }
784	        members.flush();
785	    }
786	
787	    /** Drop a person leaving the sheet from its crews: their memberships, and the crews they lead
788	     *  with those crews' members. */
789	    @Transactional
790	    public void drop(Long personId) {
791	        members.deleteAll(members.findByPersonIdOrderByIdAsc(personId));
792	        members.flush();
793	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(personId)) {
794	            members.deleteAll(members.findByCrewIdInOrderByIdAsc(List.of(crew.getId())));
795	            members.flush();
796	            crews.delete(crew);
797	        }
798	        crews.flush();
799	    }
800	}
801	-- A crew on the sheet: a name (at most once per sheet, compared ignoring case) and its lead, a
802	-- person of the sheet.
803	CREATE TABLE crew (
804	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
805	    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet (id),
806	    name       VARCHAR(200) NOT NULL,
807	    lead_id    BIGINT NOT NULL REFERENCES person (id)
808	);
809	CREATE INDEX crew_sheet ON crew (sheet_id, id);
810	
811	-- A member of a crew: a person of the sheet, at most once per crew and never its lead.
812	CREATE TABLE crew_member (
813	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
814	    crew_id    BIGINT NOT NULL REFERENCES crew (id),
815	    person_id  BIGINT NOT NULL REFERENCES person (id),
816	    UNIQUE (crew_id, person_id)
817	);
