import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';

/** A share percent: up to two decimals (more than 0.00 and at most 100.00 is checked apart). */
export const SHARE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** A from- or to-date of a membership: yyyy-mm-dd. */
export const MEMBER_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/** A person, or another pool of the sheet, in a pool with their share percent (two decimals):
 *  exactly one of personId and pool is set. The membership may carry a from- and a to-date
 *  (yyyy-mm-dd, both inclusive, null when not given). */
export interface PoolMember {
  personId: number | null;
  pool: string | null;
  share: string;
  from: string | null;
  to: string | null;
}

/** Whether the membership's dates include the day (yyyy-mm-dd): a member outside them is left out
 *  of the pool entirely. With no day known, every member is in. */
export function memberOn(m: PoolMember, day: string | null): boolean {
  if (day === null) return true;
  return (m.from === null || m.from <= day) && (m.to === null || day <= m.to);
}

/** A member's key in its row's data-testid: the person's id, or pool-<name>. */
export function memberKey(m: PoolMember): string {
  return m.pool !== null ? `pool-${m.pool}` : String(m.personId);
}

/** A pool on the sheet: its name and its members, in the order they were added. */
export interface Pool {
  name: string;
  members: PoolMember[];
}

@Injectable({ providedIn: 'root' })
export class PoolsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's pools, in the order they were added. */
  list(sheetId: string): Promise<Pool[]> {
    return firstValueFrom(this.http.get<Pool[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** Add a pool; resolves to the sheet's pools with it. */
  add(sheetId: string, name: string): Promise<Pool[]> {
    return firstValueFrom(this.http.post<Pool[]>(this.url(sheetId), { name }, { headers: this.headers() }));
  }

  /** Add a person, or another pool, to a pool with a share; resolves to the sheet's pools with them. */
  addMember(sheetId: string, pool: string, member: { personId: number } | { memberPool: string }, share: string,
    from: string, to: string): Promise<Pool[]> {
    return firstValueFrom(
      this.http.post<Pool[]>(`${this.url(sheetId)}/members`, { pool, ...member, share, from, to }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function poolError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name for the pool.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The sheet has a pool of that name already.';
  return otherError(e);
}

export function memberError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a share more than 0.00 and at most 100.00, with up to two decimals, and dates as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That person is in the pool already, or that pool is a member of a pool already.';
  if (e instanceof HttpErrorResponse && e.status === 422) return 'A pool cannot contain itself, a chain of pools is at most three deep, and a to-date is not before the from-date.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That pool or person is no longer on the sheet; load the sheet again.';
  return otherError(e);
}
import { DOCUMENT } from '@angular/common';
import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { FigurePipe } from '../../core/figure.pipe';
import { Session } from '../../core/session';
import { cents, money } from '../claims/claims-api';
import { csvLine, heldOn, type Person } from '../people/people-api';
import { dueCents } from '../rates/rates-api';
import { MEMBER_DATE_PATTERN, Pool, PoolMember, PoolsApi, SHARE_PATTERN, memberError, memberKey, memberOn, poolError } from './pools-api';

/** A pool's members' shares in cents, a member whose dates do not include the day counting 0. */
function memberShares(pool: Pool, day: string | null): number[] {
  return pool.members.map((m) => (!memberOn(m, day) ? 0 : cents(m.share)));
}

/** Whole cents times a share over the shares with a cut, in whole cents, rounded half to even
 *  (a negative product rounded as its size is). Worked in BigInt so large amounts stay exact. */
function shareOf(cents: number, share: number, total: number): number {
  const product = BigInt(cents) * BigInt(share);
  const size = product < 0n ? -product : product;
  const divisor = BigInt(total);
  const whole = size / divisor;
  const twice = (size % divisor) * 2n;
  const rounded = twice > divisor || (twice === divisor && whole % 2n === 1n) ? whole + 1n : whole;
  return Number(product < 0n ? -rounded : rounded);
}

/** Each member's cut of the pool's pot, by member key: the pot times their share divided by the
 *  shares of the members with a cut, rounded half to even, the remainder going to the member with
 *  the smallest non-zero cut (the latest added on a tie; a member with no cut gets none, and a pool
 *  with no non-zero cut gives it to the last member with a share) so the cuts total the pot. A retired
 *  member, and one held on the sheet's today, gets 0.00, their share spread over the others (all
 *  0.00 when none is left with a cut; no cuts at all when every member is retired); none unless the
 *  pool is balanced (a retirement or hold leaves the balance as it is) and has a pot. A member
 *  whose dates do not include the day is left out entirely: no cut at all. */
function cutsOf(pool: Pool, pot: string | null, retired: (personId: number) => boolean,
  held: (personId: number) => boolean, day: string | null): Map<string, string> {
  const cutsByKey = new Map<string, string>();
  const shares = memberShares(pool, day);
  if (pot === null || shares.reduce((sum, c) => sum + c, 0) !== 10000) return cutsByKey;
  const onDay = pool.members.filter((m) => memberOn(m, day));
  if (onDay.every((m) => m.personId !== null && retired(m.personId))) return cutsByKey;
  const potCents = cents(pot);
  const cutShares = pool.members.map((m, i) =>
    (m.personId !== null && (retired(m.personId) || held(m.personId)) ? 0 : shares[i]));
  const total = cutShares.reduce((sum, c) => sum + c, 0);
  const raw = cutShares.map((share) => (share === 0 ? 0 : shareOf(potCents, share, total)));
  if (total > 0) {
    let target = -1;
    raw.forEach((cut, i) => {
      if (cut !== 0 && (target < 0 || Math.abs(cut) <= Math.abs(raw[target]))) target = i;
    });
    if (target < 0) cutShares.forEach((share, i) => { if (share > 0) target = i; });
    raw[target] += potCents - raw.reduce((sum, c) => sum + c, 0);
  }
  pool.members.forEach((m, i) => { if (memberOn(m, day)) cutsByKey.set(memberKey(m), money(raw[i])); });
  return cutsByKey;
}

